int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "Packetization mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "Unsupported packetization mode: %d\n", mode);
            return AVERROR(EINVAL);
        }
        h264_data->packetization_mode = mode;
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id: %s\n", value);
            return AVERROR(EINVAL);
        }
        if (av_str2uint64(&h264_data->profile_level_id, value, 16, 6) < 0) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id: %s\n", value);
            return AVERROR(EINVAL);
        }
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        int i, num_sets, ret;
        const char *p = value;
        uint8_t *data = NULL;
        int data_size = 0;

        av_freep(&h264_data->extradata);
        h264_data->extradata_size = 0;

        while (*p) {
            int len = 0;
            const char *end = strchr(p, ',');
            if (!end) {
                end = p + strlen(p);
            }
            len = end - p;
            if (len <= 0) {
                av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets: %s\n", value);
                return AVERROR(EINVAL);
            }

            data = av_malloc(data_size + len + 1);
            if (!data) {
                ret = AVERROR(ENOMEM);
                goto fail;
            }
            memcpy(data + data_size, p, len);
            data_size += len;
            data[data_size] = 0;
            p = end + 1;
        }

        num_sets = 0;
        for (i = 0; i < data_size; i++) {
            if (!data[i]) {
                num_sets++;
            }
        }

        h264_data->extradata = data;
        h264_data->extradata_size = data_size;
        av_log(s, AV_LOG_DEBUG, "Parsed %d sprop-parameter-sets\n", num_sets);
        return 0;

fail:
        av_freep(&data);
        return ret;
    }

    return 0;
}

int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "packetization-mode %d not supported\n", mode);
            return AVERROR(EINVAL);
        }
        h264_data->packetization_mode = mode;
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id\n");
            return AVERROR(EINVAL);
        }
        av_log(s, AV_LOG_DEBUG, "profile-level-id: %s\n", value);
        av_strlcpy(h264_data->profile_level_id, value, sizeof(h264_data->profile_level_id));
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        AVIOContext *pb;
        uint8_t *data = NULL;
        int size = 0;

        if (!value || !*value) {
            av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets\n");
            return AVERROR(EINVAL);
        }

        av_freep(&h264_data->extradata);
        h264_data->extradata_size = 0;

        if (avio_open_buf(&pb, (uint8_t *)value, strlen(value), 0) < 0) {
            return AVERROR(ENOMEM);
        }

        while (!avio_feof(pb)) {
            char *p = av_malloc(1);
            if (!p) {
                avio_close(pb);
                av_freep(&data);
                return AVERROR(ENOMEM);
            }
            *p = '\0';
            avio_get_str(pb, INT_MAX, p, 1);
            av_freep(&p);
        }
        avio_close(pb);

        if (av_base64_decode(NULL, &size, (uint8_t *)value, strlen(value)) < 0) {
            av_log(s, AV_LOG_ERROR, "Failed to decode sprop-parameter-sets\n");
            return AVERROR(EINVAL);
        }

        data = av_malloc(size + AV_INPUT_BUFFER_PADDING_SIZE);
        if (!data) {
            return AVERROR(ENOMEM);
        }

        if (av_base64_decode(data, &size, (uint8_t *)value, strlen(value)) < 0) {
            av_freep(&data);
            return AVERROR(EINVAL);
        }

        h264_data->extradata = data;
        h264_data->extradata_size = size;
        av_log(s, AV_LOG_DEBUG, "sprop-parameter-sets decoded, size: %d\n", size);
    } else {
        av_log(s, AV_LOG_DEBUG, "Unknown FMTP attribute: %s\n", attr);
        return AVERROR(EINVAL);
    }
    return 0;
}

int parse_fmtp_h264_attributes(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "Unsupported packetization-mode %d\n", mode);
            return AVERROR_INVALIDDATA;
        }
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id length\n");
            return AVERROR_INVALIDDATA;
        }
        h264_data->profile_level_id[0] = value[0];
        h264_data->profile_level_id[1] = value[1];
        h264_data->profile_level_id[2] = value[2];
        h264_data->profile_level_id[3] = value[3];
        h264_data->profile_level_id[4] = value[4];
        h264_data->profile_level_id[5] = value[5];
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        uint8_t *extradata = NULL;
        int extradata_size = 0;
        int ret = parse_sprop_parameter_sets(value, &extradata, &extradata_size);
        if (ret < 0) {
            av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets\n");
            return ret;
        }
        av_freep(&stream->codecpar->extradata);
        stream->codecpar->extradata = extradata;
        stream->codecpar->extradata_size = extradata_size;
    } else {
        av_log(s, AV_LOG_WARNING, "Ignoring unknown attribute %s\n", attr);
    }

    return 0;
}

int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "packetization-mode must be 0 or 1\n");
            return AVERROR(EINVAL);
        }
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id length\n");
            return AVERROR(EINVAL);
        }
        // Convert profile-level-id to binary
        uint8_t profile[3];
        for (int i = 0; i < 3; i++) {
            sscanf(value + 2 * i, "%2hhx", &profile[i]);
        }
        h264_data->profile_id = profile[0];
        h264_data->profile_compat = profile[1];
        h264_data->level_idc = profile[2];
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        AVIOContext *pb = NULL;
        uint8_t *data = NULL;
        int size = 0;
        if (!av_b64_decode(&data, &size, value)) {
            avio_close(pb);
            av_freep(&data);
            av_log(s, AV_LOG_ERROR, "Invalid base64 encoding for sprop-parameter-sets\n");
            return AVERROR(EINVAL);
        }
        av_freep(&h264_data->extradata);
        h264_data->extradata = data;
        h264_data->extradata_size = size;
        av_log(s, AV_LOG_DEBUG, "sprop-parameter-sets parsed, size: %d\n", size);
    } else {
        av_log(s, AV_LOG_DEBUG, "Ignoring unknown attribute: %s\n", attr);
        return 0;
    }

    return 0;
}
